package com.example.musicapp.cache

import androidx.compose.ui.graphics.ImageBitmap
import androidx.compose.ui.graphics.toPixelMap
import com.example.musicapp.platform.decodeImageBytes
import kotlin.test.Test
import kotlin.test.assertNotNull

class PixelMapTest {
    @Test
    fun testToPixelMapOnSkiaBitmap() {
        // Minimal 1x1 PNG bytes
        val pngBytes = byteArrayOf(
            0x89.toByte(), 0x50.toByte(), 0x4E.toByte(), 0x47.toByte(), 0x0D.toByte(), 0x0A.toByte(), 0x1A.toByte(), 0x0A.toByte(),
            0x00, 0x00, 0x00, 0x0D, 0x49, 0x48, 0x44, 0x52, 0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x01, 0x08, 0x06, 0x00, 0x00, 0x00, 0x1F, 0x15, 0xC4.toByte(), 0x89.toByte(),
            0x00, 0x00, 0x00, 0x0D, 0x49, 0x44, 0x41, 0x54, 0x78, 0x9C.toByte(), 0x63, 0x60, 0x60, 0x60, 0xF8.toByte(), 0x0F, 0x00, 0x01, 0x04, 0x01, 0x00, 0x18, 0xDD.toByte(), 0x8D.toByte(), 0xB0.toByte(),
            0x00, 0x00, 0x00, 0x00, 0x49, 0x45, 0x4E, 0x44, 0xAE.toByte(), 0x42, 0x60, 0x82.toByte()
        )
        val bmp = decodeImageBytes(pngBytes)
        assertNotNull(bmp)
        val color = ArtworkCache.computeAndStoreDominantColor("test_path", bmp)
        assertNotNull(color)
    }
}
